function convert(nodes: PmNode[], ctx: Ctx): Content[] {
  const out: Content[] = [];
  for (const node of nodes) {
    switch (node.type) {
      case "paragraph":
        out.push(...paragraph(node, ctx));
        break;
      case "heading": {
        const level = Number(node.attrs?.level) || 1;
        out.push({ text: runs(node.content, ctx), fontSize: HEADING_SIZE[level] ?? 12, bold: true, alignment: align(node), margin: [0, 8, 0, 6] } as Content);
        break;
      }
      case "bulletList":
        out.push({ ul: (node.content ?? []).map((i) => listItem(i, ctx)), margin: [0, 0, 0, 6] } as Content);
        break;
      case "orderedList":
        out.push({ ol: (node.content ?? []).map((i) => listItem(i, ctx)), margin: [0, 0, 0, 6] } as Content);
        break;
      case "blockquote":
        out.push({ stack: convert(node.content ?? [], ctx), italics: true, color: MUTED, margin: [12, 0, 0, 5] } as Content);
        break;
      case "horizontalRule":
        out.push({ canvas: [{ type: "line", x1: 0, y1: 0, x2: 512, y2: 0, lineWidth: 0.75, lineColor: LINE }], margin: [0, 6, 0, 6] } as Content);
        break;
      case "image": {
        const img = image(node);
        if (img) out.push(img);
        break;
      }
      case "table":
        out.push(table(node, ctx));
        break;
      case "banner":
        out.push(banner(node, ctx));
        break;
      case "linesTable":
        out.push(linesTable(ctx));
        break;
      case "pageBreak":
        out.push({ text: "", pageBreak: "before" } as Content);
        break;
      default:
        if (node.content) out.push(...convert(node.content, ctx));
    }
  }
  return out;
}

