/** Builds the PDF of an order from a document written in the editor. */
export function renderDocument(content: TemplateContent, order: Order): Promise<Uint8Array> {
  const values = buildValues(order);
  const base: Ctx = { values, order };
  const side = (doc: { content?: PmNode[] } | undefined, margin: [number, number, number, number]) =>
    doc ? (page: number, pages: number): Content => ({ margin, stack: convert(prepare(doc.content ?? [], values), { ...base, page: { page, pages } }) }) : undefined;

  const definition: TDocumentDefinitions = {
    info: { title: order.folio },
    pageSize: "LETTER",
    pageMargins: [50, content.header ? 100 : 50, 50, content.footer ? 76 : 50],
    defaultStyle: { font: "Roboto", fontSize: 10, lineHeight: 1.25, color: INK },
    header: side(content.header, [50, 28, 50, 0]),
    footer: side(content.footer, [50, 12, 50, 0]),
    content: convert(prepare(content.body.content ?? [], values), base),
  };

  return new Promise((resolve, reject) => {
    try {
      (pdfMake.createPdf(definition) as unknown as { getBuffer(done: (buffer: Uint8Array) => void): void }).getBuffer((buffer) => resolve(new Uint8Array(buffer)));
    } catch (err) {
      reject(err);
    }
  });
}
